def hydrate_time(nanoseconds, tz=None):
    nanoseconds = int(nanoseconds)
    if tz:
        tz = pendulum.Timezone.in_tz(tz)
    else:
        tz = pendulum.now(pendulum.UTC)
    tz_offset = tz.get_offset(pendulum.DateTime.from_timestamp(nanoseconds / 1e9))
    nanoseconds += tz_offset.total_seconds() * 1e9
    return pendulum.Time.from_timestamp(nanoseconds / 1e9, tz)

