def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    "spec.manifest" for which a custom observer schema hasn't been specified.

    :param app: The application for which to generate a default observer schema
    :type app: krake.data.kubernetes.Application
    """
    default_schema = {
        "kind": "ClusterRole",
        "apiVersion": "rbac.authorization.k8s.io/v1",
        "metadata": {
            "name": "default-observer-role"
        },
        "rules": [
            {
                "apiGroups": [
                    ""
                ],
                "resources": [
                    "pods",
                    "services",
                    "configmaps",
                    "endpoints",
                    "secrets"
                ],
                "verbs": [
                    "get",
                    "watch",
                    "list",
                    "create"
                ]
            }
        ]
    }

    # initialize the observer schema
    observer_schema = {}

    # iterate over the resources in the manifest
    for resource in app.spec.manifest.resources:
        # get the name of the resource
        resource_name = resource.metadata.name

        # check if a custom observer schema has been defined for this resource
        if resource_name not in app.observer_schema:
            # if not, use the default observer schema
            observer_schema[resource_name] = default_schema
        else:
            # if a custom observer schema has been defined, use it
            observer_schema[resource_name] = app.observer_schema[resource_name]

    return observer_schema

