def format(
	self,
	sql: AnyStr,
	params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
	if not isinstance(sql, str):
		sql = str(sql, "utf-8")

	out_params = {}
	for param in params:
		pname, pvalue = (param if isinstance(param, str) else param[0], param if isinstance(param, str) else param[1])
		if pname in out_params:
			raise ValueError(f"Duplicate parameter '{pname}' in SQL statement.")

		out_params[pname] = pvalue

	return (sql.replace("?", "%s"), out_params)

