def format_many(sql, many_params):
    # Convert the SQL query to use the out-style parameters instead of the in-style parameters
    if isinstance(many_params[0], Mapping):
        # many_params contains dicts, convert to lists
        many_params = list(map(lambda x: list(x.values()), many_params))
    elif isinstance(many_params[0], Sequence):
        # many_params contains sequences, no conversion necessary
        pass
    else:
        # invalid data type in many_params, raise TypeError
        raise TypeError("Invalid type in many_params")

    # Initialize out-style parameters
    out_params = []

    # Iterate over each set of in-style parameters
    for params in many_params:
        # Convert the in-style parameters to out-style parameters
        out_params.append(convert_params(sql, params))

    # Return the formatted SQL query and the out-style parameters
    return (sql, out_params)

def convert_params(sql, params):
    # Convert the in-style parameters to out-style parameters
    out_params = {}
    for key, value in params.items():
        # Get the parameter marker for the current key
        # If the key is a string, use ? as the marker
        # If the key is a number, use %s as the marker
        if isinstance(key, str):
            marker = "?"
        elif isinstance(key, int):
            marker = "%s"
        else:
            # Invalid key type, raise TypeError
            raise TypeError(f"Invalid type in params key: {key}")

        # Add the parameter to the out-style parameters
        out_params[marker] = value

    # Return the out-style parameters
    return out_params

