def validate_as_prior_version(self: 'InventoryValidator', prior: 'InventoryValidator'):
    """
    Check that prior is a valid prior version of the current inventory object.
    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if prior.version > self.version:
        raise ValueError(
            f"prior version ({prior.version}) cannot be greater than "
            f"the current version ({self.version})"
        )
    if prior.found_by != self.found_by:
        raise ValueError(
            f"prior inventory ({prior.found_by}) must be found by the same person "
            f"as the current inventory ({self.found_by})"
        )
    if prior.found_on != self.found_on:
        raise ValueError(
            f"prior inventory ({prior.found_on}) must be found on the same date as "
            f"the current inventory ({self.found_on})"
        )
    if prior.items != self.items:
        raise ValueError(
            f"prior inventory ({prior.items}) must contain the same items as "
            f"the current inventory ({self.items})"
        )

