def get_logical_path_map(inventory, version) -> Dict[str, Set[str]]:
    logical_path_map: Dict[str, Set[str]] = {}
    for state in inventory:
        for content_file in state.content_files:
            if content_file.version <= version:
                logical_path = content_file.logical_path
                if logical_path not in logical_path_map:
                    logical_path_map[logical_path] = set()
                logical_path_map[logical_path].add(content_file)
    return logical_path_map

