def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    if validate_objects:
        # Loop through the storage root hierarchy and validate all objects
        for obj in self.objects:
            num_objects += 1
            if obj.is_valid():
                good_objects += 1

    if check_digests:
        # Check that the digests of each object match the stored digest
        for obj in self.objects:
            if not obj.check_digest():
                if show_warnings:
                    self.logger.warning("Object digest mismatch: {}".format(obj))
                else:
                    num_objects -= 1   # Don't count this object as checked

    return num_objects, good_objects

